xhtml:pre.style:
width:100%;
height:100%;
box-sizing:border-box;
margin:0;
padding:20px;
overflow:auto;
white-space:pre-wrap;
word-break:break-word;
font-family:monospace;

svg.script:
const ROOT =
  "https://cdn.jsdelivr.net/gh/NotReallyRx/bocchi@main/a/html/";

const output =
  document.getElementById("output");

async function getLinks(url) {
  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(
      response.status + " " +
      response.statusText + ": " + url
    );
  }

  const html = await response.text();

  const doc =
    new DOMParser().parseFromString(
      html,
      "text/html"
    );

  return [...doc.querySelectorAll("a[href]")]
    .map(a => a.href)
    .filter(Boolean);
}

async function scan() {
  const queue = [ROOT];
  const visited = new Set();
  const files = [];

  const rootUrl = new URL(ROOT);

  while (queue.length) {
    const directory = queue.shift();

    if (visited.has(directory)) continue;

    visited.add(directory);

    const links = await getLinks(directory);

    for (const link of links) {
      const url = new URL(link);

      url.search = "";
      url.hash = "";

      if (
        url.origin !== rootUrl.origin ||
        !url.pathname.startsWith(rootUrl.pathname)
      ) {
        continue;
      }

      if (url.href === directory) continue;

      const relativePath =
        decodeURIComponent(
          url.pathname.slice(
            rootUrl.pathname.length
          )
        );

      if (!relativePath) continue;

      if (relativePath.endsWith("/")) {
        if (!visited.has(url.href)) {
          queue.push(url.href);
        }
      } else {
        files.push(relativePath);
      }
    }
  }

  return [...new Set(files)].sort();
}

async function main() {
  try {
    const files = await scan();

    output.textContent = JSON.stringify({
      repository: "NotReallyRx/bocchi",
      root: "a/html",
      count: files.length,
      files
    }, null, 2);

    window.fileIndex = {
      repository: "NotReallyRx/bocchi",
      root: "a/html",
      count: files.length,
      files
    };

  } catch (error) {
    output.textContent =
      JSON.stringify({
        error: error.message
      }, null, 2);
  }
}

main();
